import Foundation
import GameKit

/// Offline lives: 5 max, one regenerates every 20 minutes of wall-clock time. Pure logic, no UI.
enum Lives {
    static let MAX = 5
    static let REGEN_MS: Int64 = 20 * 60 * 1000

    struct State: Equatable {
        let lives: Int
        let nextLifeAtMillis: Int64

        var isFull: Bool { lives >= MAX }
    }

    /// Applies every life that has regenerated by [now]. Clamps a timer that is too far in the future (clock moved back).
    static func refresh(_ lives: Int, _ nextLifeAtMillis: Int64, _ now: Int64) -> State {
        if lives >= MAX { return State(MAX, 0) }
        var l = lives.coerceAtLeast(0)
        var next = nextLifeAtMillis
        if next <= 0 { next = now + REGEN_MS }
        if next - now > REGEN_MS { next = now + REGEN_MS }
        while l < MAX && now >= next {
            l += 1
            next += REGEN_MS
        }
        return l >= MAX ? State(MAX, 0) : State(l, next)
    }

    /// Spends one life (after applying regeneration).
    static func consume(_ lives: Int, _ nextLifeAtMillis: Int64, _ now: Int64) -> State {
        let s = refresh(lives, nextLifeAtMillis, now)
        if s.lives <= 0 { return s }
        let next = s.nextLifeAtMillis == 0 ? now + REGEN_MS : s.nextLifeAtMillis
        return State(s.lives - 1, next)
    }

    /// Adds one life back (used when a lost level is continued).
    static func refund(_ lives: Int, _ nextLifeAtMillis: Int64, _ now: Int64) -> State {
        let s = refresh(lives, nextLifeAtMillis, now)
        let l = (s.lives + 1).coerceAtMost(MAX)
        return l >= MAX ? State(MAX, 0) : State(l, s.nextLifeAtMillis)
    }

    /// "Full" or mm:ss until the next life.
    static func timerText(_ state: State, _ now: Int64) -> String {
        if state.isFull { return "Full" }
        let remain = (state.nextLifeAtMillis - now).coerceAtLeast(0)
        return formatMmSs(remain)
    }

    /// Kotlin `"%02d:%02d".format(m, s)` (ASCII digits, at least two per field).
    static func formatMmSs(_ millis: Int64) -> String {
        let totalSec = (millis + 999) / 1000
        let m = totalSec / 60
        let s = totalSec % 60
        return pad2(m) + ":" + pad2(s)
    }

    /// `%02d`: zero-padded to width 2 (a minus sign already fills the width).
    private static func pad2(_ v: Int64) -> String {
        let d = String(v)
        return d.count < 2 ? "0" + d : d
    }
}

extension Lives.State {
    init(_ lives: Int, _ nextLifeAtMillis: Int64) {
        self.lives = lives
        self.nextLifeAtMillis = nextLifeAtMillis
    }
}
